def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 4:
        if history[-1][1] == 'D':
            return 'D'
        return 'C'
    if n >= 99:
        return 'D'

    last_my, last_opp = history[-1]
    prev_my = history[-2][0] if n >= 2 else 'C'

    opp_d = 0
    my_d = 0
    forg = 0
    pun = 0
    unprov = 0
    recent_opp_d = 0
    recent_my_d = 0

    start = n - 12
    if start < 0:
        start = 0

    prev_a = 'C'
    for i in range(n):
        a, b = history[i]

        if a == 'D':
            my_d += 1
            if i >= start:
                recent_my_d += 1

        if b == 'D':
            opp_d += 1
            if i >= start:
                recent_opp_d += 1

        if i > 0:
            if prev_a == 'D':
                if b == 'C':
                    forg += 1
                else:
                    pun += 1
            else:
                if b == 'D':
                    unprov += 1

        prev_a = a

    if opp_d == n:
        return 'D'

    if opp_d * 2 > n:
        return 'D'

    if recent_opp_d >= 6 and opp_d * 5 > n:
        return 'D'

    if opp_d == 0:
        if n == 4:
            return 'D'
        if n < 8:
            return 'C'
        return 'D'

    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    exploitable = False
    if opp_d * 6 <= n:
        if forg >= 1 and pun == 0:
            exploitable = True
        if forg >= 2 and pun < forg:
            exploitable = True
    if opp_d * 3 <= n:
        if forg >= 3 and pun < forg:
            exploitable = True

    if recent_opp_d >= 5:
        exploitable = False
    if my_d == 1 and n < 8:
        exploitable = False

    if last_opp == 'D':
        if last_my == 'D':
            if opp_d * 3 <= n or recent_opp_d <= 3:
                return 'C'
            if recent_my_d <= 2 and rng.random() < 0.4:
                return 'C'
            return 'D'

        if prev_my == 'D':
            if recent_opp_d >= 5:
                return 'D'
            return 'C'

        if (recent_my_d > 0 and opp_d * 4 <= n and unprov <= 3 and opp_d_streak <= 4):
            return 'C'

        return 'D'

    if last_opp == 'C':
        if last_my == 'D':
            if my_d == 1:
                return 'C'
            if exploitable:
                return 'D'
            return 'C'

        if exploitable:
            return 'D'
        return 'C'

    return 'C'
